function compatSubstring(compatLocalText: string, compatLocalStart: number, compatLocalEnd: number, compatLocalHasEnd: boolean): string {
  let compatLocalLength: number = strings.length(compatLocalText);
  let compatLocalA: number = math.min(math.max(compatLocalStart, 0), compatLocalLength);
  let compatLocalB: number = compatLocalLength;
  compatLocalA = math.floor(compatLocalA);
  if (compatLocalHasEnd) { compatLocalB = math.floor(math.min(math.max(compatLocalEnd, 0), compatLocalLength)); }
  if (compatLocalA > compatLocalB) { let compatLocalTemp: number = compatLocalA; compatLocalA = compatLocalB; compatLocalB = compatLocalTemp; }
  return strings.substring(compatLocalText, compatLocalA, compatLocalB);
}

function upperFirst(str: string): string {
return (strings.toUpperCase(compatSubstring(str, 0, 1, true)) + compatSubstring(str, 1, 0, false));
}

function compatSubstring(compatLocalText: string, compatLocalStart: number, compatLocalEnd: number, compatLocalHasEnd: boolean): string {
  let compatLocalLength: number = strings.length(compatLocalText);
  let compatLocalA: number = math.min(math.max(compatLocalStart, 0), compatLocalLength);
  let compatLocalB: number = compatLocalLength;
  compatLocalA = math.floor(compatLocalA);
  if (compatLocalHasEnd) { compatLocalB = math.floor(math.min(math.max(compatLocalEnd, 0), compatLocalLength)); }
  if (compatLocalA > compatLocalB) { let compatLocalTemp: number = compatLocalA; compatLocalA = compatLocalB; compatLocalB = compatLocalTemp; }
  return strings.substring(compatLocalText, compatLocalA, compatLocalB);
}

function lowerFirst(str: string): string {
return (strings.toLowerCase(compatSubstring(str, 0, 1, true)) + compatSubstring(str, 1, 0, false));
}

function replaceInOrder(text: string, first: string, second: string, replacement: string): string {
  return strings.replace(strings.replace(text, first, replacement), second, replacement);
}

function surroundMatches(text: string, search: string, opening: string, closing: string): string {
  return strings.replace(text, search, opening + search + closing);
}

function textBeforeDelimiter(text: string, delimiter: string): string {
  let parts: string[] = strings.split(text, delimiter);
  return parts[0];
}

function textAfterDelimiter(text: string, delimiter: string): string {
  let parts: string[] = strings.split(text, delimiter);
  if (parts.length() === 1) { return ""; }
  return strings.substring(text, strings.length(parts[0]) + strings.length(delimiter), strings.length(text));
}

function decayedAmount(initial: number, retention: number, periods: number): number {
  return initial * math.pow(retention, periods);
}

function growthDifference(initial: number, rate: number, periods: number): number {
  return initial * math.pow(1 + rate, periods) - initial;
}

function seedBucketAfterStep(seed: number, bound: number): number {
  return math.randomBelow(math.randomStep(seed), bound);
}

function seedSequence(seed: number, count: number): number[] {
  let state: number = seed;
  let result: number[] = [];
  let index: number = 0;
  while (index < count) { state = math.randomStep(state); result.push(state); index = index + 1; }
  return result;
}
